ALTER TABLE public.profiles ADD COLUMN activo boolean NOT NULL DEFAULT true;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('role',true) <> 'service_role' AND coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'Altas públicas deshabilitadas'; END IF; INSERT INTO public.profiles(id,username,nombre) VALUES(new.id,split_part(new.email,'@',1),coalesce(new.raw_user_meta_data->>'nombre',split_part(new.email,'@',1))); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'user'); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.is_active(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_uid AND activo) $$;
REVOKE ALL ON FUNCTION public.is_active(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_active(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.is_manager() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active(auth.uid()) AND public.has_role(auth.uid(),'admin') $$;
REVOKE ALL ON FUNCTION public.is_manager() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_manager() TO authenticated,service_role;
DO $$ DECLARE p record; BEGIN FOR p IN SELECT tablename,policyname FROM pg_policies WHERE schemaname='public' AND tablename IN ('profiles','user_roles','fichajes','correcciones') LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,p.tablename); END LOOP; END $$;
REVOKE ALL ON public.profiles,public.user_roles,public.fichajes,public.correcciones FROM anon,authenticated;
GRANT SELECT ON public.profiles,public.user_roles,public.fichajes,public.correcciones TO authenticated; GRANT INSERT ON public.fichajes TO authenticated; GRANT UPDATE(nombre,activo) ON public.profiles TO authenticated;
CREATE POLICY perfiles_lectura ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_manager());
CREATE POLICY perfiles_encargado ON public.profiles FOR UPDATE TO authenticated USING(public.is_manager()) WITH CHECK(public.is_manager());
CREATE POLICY roles_lectura ON public.user_roles FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.is_active(auth.uid())) OR public.is_manager());
CREATE POLICY fichajes_lectura ON public.fichajes FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.is_active(auth.uid())) OR public.is_manager());
CREATE POLICY fichajes_actuales ON public.fichajes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_active(auth.uid()));
CREATE POLICY correcciones_legacy_lectura ON public.correcciones FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.is_active(auth.uid())) OR public.is_manager());
COMMENT ON TABLE public.correcciones IS 'DEPRECATED: legacy audit history retained; new requests in solicitudes_correccion';
CREATE TABLE public.aceptaciones_ubicacion(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,version text NOT NULL DEFAULT 'ubicacion-v1',aceptada_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.aceptaciones_ubicacion TO authenticated; GRANT ALL ON public.aceptaciones_ubicacion TO service_role;
ALTER TABLE public.aceptaciones_ubicacion ENABLE ROW LEVEL SECURITY;
CREATE POLICY aceptaciones_lectura ON public.aceptaciones_ubicacion FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.is_active(auth.uid())) OR public.is_manager());
CREATE POLICY aceptaciones_crear ON public.aceptaciones_ubicacion FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_active(auth.uid()));
CREATE OR REPLACE FUNCTION public.accept_location() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.user_id=auth.uid(); NEW.version='ubicacion-v1'; NEW.aceptada_at=now(); RETURN NEW; END $$;
CREATE TRIGGER aceptar_ubicacion BEFORE INSERT ON public.aceptaciones_ubicacion FOR EACH ROW EXECUTE FUNCTION public.accept_location();
CREATE TABLE public.solicitudes_correccion(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,solicitada_por uuid NOT NULL,solicitada_at timestamptz NOT NULL DEFAULT now(),motivo text NOT NULL,propuesta jsonb NOT NULL);
GRANT SELECT ON public.solicitudes_correccion TO authenticated; GRANT ALL ON public.solicitudes_correccion TO service_role;
ALTER TABLE public.solicitudes_correccion ENABLE ROW LEVEL SECURITY;
CREATE POLICY solicitudes_lectura ON public.solicitudes_correccion FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.is_active(auth.uid())) OR public.is_manager());
CREATE TABLE public.decisiones_correccion(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),solicitud_id uuid NOT NULL UNIQUE REFERENCES public.solicitudes_correccion(id),aprobada boolean NOT NULL,decidida_por uuid NOT NULL,decidida_at timestamptz NOT NULL DEFAULT now(),motivo text NOT NULL);
GRANT SELECT ON public.decisiones_correccion TO authenticated; GRANT ALL ON public.decisiones_correccion TO service_role;
ALTER TABLE public.decisiones_correccion ENABLE ROW LEVEL SECURITY;
CREATE POLICY decisiones_lectura ON public.decisiones_correccion FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.solicitudes_correccion s WHERE s.id=solicitud_id));
CREATE OR REPLACE FUNCTION public.no_mutations() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Registro inmutable: solicite una corrección'; END $$;
CREATE TRIGGER fichajes_inmutables BEFORE UPDATE OR DELETE ON public.fichajes FOR EACH ROW EXECUTE FUNCTION public.no_mutations();
CREATE TRIGGER solicitudes_inmutables BEFORE UPDATE OR DELETE ON public.solicitudes_correccion FOR EACH ROW EXECUTE FUNCTION public.no_mutations();
CREATE TRIGGER decisiones_inmutables BEFORE UPDATE OR DELETE ON public.decisiones_correccion FOR EACH ROW EXECUTE FUNCTION public.no_mutations();
CREATE TRIGGER aceptaciones_inmutables BEFORE UPDATE OR DELETE ON public.aceptaciones_ubicacion FOR EACH ROW EXECUTE FUNCTION public.no_mutations();
CREATE TRIGGER legacy_inmutable BEFORE UPDATE OR DELETE ON public.correcciones FOR EACH ROW EXECUTE FUNCTION public.no_mutations();
CREATE OR REPLACE FUNCTION public.effective_punches(_uid uuid) RETURNS TABLE(id text,user_id uuid,tipo text,at timestamptz,dia date,lugar text,editado boolean,lat float8,lng float8,original_at timestamptz,original_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH approved AS (SELECT s.*,d.decidida_at FROM solicitudes_correccion s JOIN decisiones_correccion d ON d.solicitud_id=s.id AND d.aprobada WHERE s.user_id=_uid), changes AS (SELECT a.id sid,a.decidida_at,e.value v,e.ordinality n FROM approved a CROSS JOIN LATERAL jsonb_array_elements(a.propuesta) WITH ORDINALITY e), latest AS (SELECT DISTINCT ON (v->>'original_id') * FROM changes WHERE v->>'original_id' IS NOT NULL ORDER BY v->>'original_id',decidida_at DESC,sid DESC), events AS (
SELECT f.id::text id,f.user_id,coalesce(l.v->>'tipo',f.tipo) tipo,coalesce((l.v->>'at')::timestamptz,f.at) at,f.lugar,(f.editado OR l.sid IS NOT NULL) editado,f.lat,f.lng,f.at original_at,f.id original_id FROM fichajes f LEFT JOIN latest l ON l.v->>'original_id'=f.id::text WHERE f.user_id=_uid AND coalesce((l.v->>'anular')::boolean,false)=false
UNION ALL SELECT sid::text||':'||n,_uid,v->>'tipo',(v->>'at')::timestamptz,'Centro principal',true,NULL::float8,NULL::float8,NULL::timestamptz,NULL::uuid FROM changes WHERE v->>'original_id' IS NULL AND NOT coalesce((v->>'anular')::boolean,false)
), sessions AS (SELECT *,sum(CASE WHEN tipo='entrada' THEN 1 ELSE 0 END) OVER(ORDER BY at,id) session FROM events)
SELECT id,user_id,tipo,at,coalesce((min(at) FILTER(WHERE tipo='entrada') OVER(PARTITION BY session) AT TIME ZONE 'Europe/Madrid')::date,(at AT TIME ZONE 'Europe/Madrid')::date),lugar,editado,lat,lng,original_at,original_id FROM sessions ORDER BY at,id $$;
REVOKE ALL ON FUNCTION public.effective_punches(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.list_punches(_uid uuid DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active(auth.uid()) THEN RAISE EXCEPTION 'Cuenta inactiva'; END IF; IF _uid IS NULL AND NOT public.is_manager() THEN _uid=auth.uid(); END IF; IF _uid IS NOT NULL AND _uid<>auth.uid() AND NOT public.is_manager() THEN RAISE EXCEPTION 'Sin permiso'; END IF; RETURN QUERY SELECT to_jsonb(e) FROM profiles p CROSS JOIN LATERAL public.effective_punches(p.id) e WHERE _uid IS NULL OR p.id=_uid; END $$;
REVOKE ALL ON FUNCTION public.list_punches(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.list_punches(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_punch_sequence(_uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e record; st text='fuera'; prev timestamptz; BEGIN FOR e IN SELECT * FROM public.effective_punches(_uid) LOOP IF prev IS NOT NULL AND e.at<=prev THEN RAISE EXCEPTION 'Las horas deben ser distintas y crecientes'; END IF; IF (st='fuera' AND e.tipo<>'entrada') OR (st='trabajando' AND e.tipo NOT IN ('pausa','salida')) OR (st='pausa' AND e.tipo NOT IN ('reanudar','salida')) THEN RAISE EXCEPTION 'Secuencia de fichajes inválida'; END IF; st=CASE e.tipo WHEN 'entrada' THEN 'trabajando' WHEN 'reanudar' THEN 'trabajando' WHEN 'pausa' THEN 'pausa' ELSE 'fuera' END; prev=e.at; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.validate_punch_sequence(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.current_punch() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE last_p record; st text='fuera'; BEGIN IF auth.uid() IS NULL OR NOT public.is_active(auth.uid()) THEN RAISE EXCEPTION 'Cuenta inactiva'; END IF; NEW.user_id=auth.uid(); PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0)); SELECT * INTO last_p FROM public.effective_punches(NEW.user_id) ORDER BY at DESC LIMIT 1; IF FOUND THEN st=CASE last_p.tipo WHEN 'entrada' THEN 'trabajando' WHEN 'reanudar' THEN 'trabajando' WHEN 'pausa' THEN 'pausa' ELSE 'fuera' END; END IF; IF (st='fuera' AND NEW.tipo<>'entrada') OR (st='trabajando' AND NEW.tipo NOT IN ('pausa','salida')) OR (st='pausa' AND NEW.tipo NOT IN ('reanudar','salida')) THEN RAISE EXCEPTION 'Secuencia inválida'; END IF; NEW.at=now(); NEW.created_at=now(); NEW.editado=false; NEW.lugar='Centro principal'; NEW.dia=CASE WHEN st<>'fuera' THEN last_p.dia ELSE (NEW.at AT TIME ZONE 'Europe/Madrid')::date END; IF (NEW.lat IS NOT NULL OR NEW.lng IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM aceptaciones_ubicacion WHERE user_id=NEW.user_id AND version='ubicacion-v1') THEN RAISE EXCEPTION 'Debe aceptar el aviso de ubicación'; END IF; IF NEW.lat IS NULL OR NEW.lng IS NULL THEN NEW.lat=NULL; NEW.lng=NULL; NEW.precision_m=NULL; END IF; IF NEW.lat NOT BETWEEN -90 AND 90 OR NEW.lng NOT BETWEEN -180 AND 180 OR NEW.precision_m<0 THEN RAISE EXCEPTION 'Ubicación inválida'; END IF; RETURN NEW; END $$;
CREATE TRIGGER fichaje_actual BEFORE INSERT ON public.fichajes FOR EACH ROW EXECUTE FUNCTION public.current_punch();
CREATE OR REPLACE FUNCTION public.request_correction(_uid uuid,_motivo text,_propuesta jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; rid uuid; BEGIN IF NOT public.is_active(auth.uid()) OR (_uid<>auth.uid() AND NOT public.is_manager()) OR NOT public.is_active(_uid) THEN RAISE EXCEPTION 'Sin permiso'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_uid::text,0)); IF length(trim(_motivo))<1 OR jsonb_typeof(_propuesta)<>'array' OR jsonb_array_length(_propuesta) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Motivo y propuesta obligatorios'; END IF; FOR x IN SELECT value FROM jsonb_array_elements(_propuesta) LOOP IF x->>'original_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fichajes WHERE id=(x->>'original_id')::uuid AND user_id=_uid) THEN RAISE EXCEPTION 'Original no pertenece al trabajador'; END IF; IF coalesce((x->>'anular')::boolean,false) AND x->>'original_id' IS NULL THEN RAISE EXCEPTION 'Anulación sin original'; END IF; IF NOT coalesce((x->>'anular')::boolean,false) AND (x->>'tipo' IS NULL OR x->>'tipo' NOT IN ('entrada','pausa','reanudar','salida') OR x->>'at' IS NULL OR (x->>'at')::timestamptz>now()) THEN RAISE EXCEPTION 'Hora o tipo inválidos'; END IF; END LOOP; IF EXISTS(SELECT 1 FROM jsonb_array_elements(_propuesta) x WHERE x->>'original_id' IS NOT NULL GROUP BY x->>'original_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Original repetido'; END IF; INSERT INTO solicitudes_correccion(user_id,solicitada_por,motivo,propuesta) VALUES(_uid,auth.uid(),trim(_motivo),_propuesta) RETURNING id INTO rid; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.request_correction(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_correction(uuid,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.decide_correction(_id uuid,_aprobar boolean,_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s solicitudes_correccion; BEGIN IF NOT public.is_manager() THEN RAISE EXCEPTION 'Solo encargado'; END IF; SELECT * INTO s FROM solicitudes_correccion WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud inexistente'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(s.user_id::text,0)); IF EXISTS(SELECT 1 FROM decisiones_correccion WHERE solicitud_id=_id) THEN RAISE EXCEPTION 'Ya decidida'; END IF; IF length(trim(_motivo))<1 THEN RAISE EXCEPTION 'Motivo obligatorio'; END IF; INSERT INTO decisiones_correccion(solicitud_id,aprobada,decidida_por,motivo) VALUES(_id,_aprobar,auth.uid(),trim(_motivo)); IF _aprobar THEN PERFORM public.validate_punch_sequence(s.user_id); END IF; END $$;
REVOKE ALL ON FUNCTION public.decide_correction(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_correction(uuid,boolean,text) TO authenticated;